[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$JobRoot,[Parameter(Mandatory=$true)][string]$AttemptId,[string]$RepositoryRoot)
$ErrorActionPreference='Stop';if(-not $RepositoryRoot){$RepositoryRoot=Split-Path -Parent $PSScriptRoot};$RepositoryRoot=[IO.Path]::GetFullPath($RepositoryRoot);$JobRoot=[IO.Path]::GetFullPath($JobRoot);$attemptRoot=Join-Path $JobRoot (Join-Path 'output' $AttemptId);if(Test-Path $attemptRoot){throw "Attempt exists: $attemptRoot"}
$source=Join-Path $RepositoryRoot 'src\fg_connected_custom_l56_l83\rtx_connected_l56_l83.cpp';$contract=Join-Path $RepositoryRoot 'src\fg_connected_custom_l56_l83\contract.h';$baseSource=Join-Path $RepositoryRoot 'src\fg_conv\rtx_oracle.cpp';$modules=Join-Path $JobRoot 'inputs\modules';$model=Join-Path $JobRoot 'inputs\model';$manifest=Join-Path $model 'runtime-default-buffers-post-evaluate-0.manifest.json';foreach($required in @($source,$contract,$baseSource,$manifest)){if(-not(Test-Path $required -PathType Leaf)){throw "Missing $required"}};if((Get-FileHash $manifest -Algorithm SHA256).Hash -ne '2A1179D4A25BE030F772CD90CA7D017ED6EAC9291917F7D43EA9B0CD5AC6A294'){throw 'Manifest mismatch'}
$cudaPath=$env:CUDA_PATH;if(-not $cudaPath){$cudaPath='C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$installation=& $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vcvars=Join-Path $installation 'VC\Auxiliary\Build\vcvars64.bat';$build=Join-Path $attemptRoot 'build';New-Item -ItemType Directory -Path $build|Out-Null;$binary=Join-Path $build 'connected-l56-l83.exe';$object=Join-Path $build 'connected-l56-l83.obj';$log=Join-Path $build 'compile.log';$command='"{0}" >nul && cl.exe /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /Zc:__cplusplus /utf-8 /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && link.exe /nologo /OUT:"{5}" "{2}" "{6}" bcrypt.lib >>"{4}" 2>&1' -f $vcvars,(Join-Path $cudaPath 'include'),$object,$source,$log,$binary,(Join-Path $cudaPath 'lib\x64\cuda.lib');& $env:ComSpec /d /s /c $command;if($LASTEXITCODE -ne 0){throw "Build failed: $log"}
$receipts=@();foreach($poison in @('a5','5a')){foreach($ordinal in @('a','b')){$id="connected-l56-l83-poison-$poison-process-$ordinal";$run=Join-Path $attemptRoot $id;New-Item -ItemType Directory -Path $run|Out-Null;$p=Start-Process -FilePath $binary -ArgumentList @($modules,$model,$run,$id,$poison) -NoNewWindow -Wait -PassThru -RedirectStandardOutput (Join-Path $run 'stdout.log') -RedirectStandardError (Join-Path $run 'stderr.log');if($p.ExitCode-ne 0){throw "Run failed $id"};$receipts+=Get-Content (Join-Path $run 'run-receipt.json') -Raw|ConvertFrom-Json}}
$final=@($receipts|ForEach-Object{$_.final_output_sha256}|Sort-Object -Unique);$pids=@($receipts|ForEach-Object{$_.process_id}|Sort-Object -Unique);$checkpoints=@($receipts|ForEach-Object{($_.checkpoint_sha256|ConvertTo-Json -Compress)}|Sort-Object -Unique);if($final.Count-ne 1-or$pids.Count-ne 4-or$checkpoints.Count-ne 1){throw 'repeat/poison checkpoint gate'}
$receipt=[ordered]@{schema='neuralstudio.fg.connected-custom-l56-l83-rig.v1';job_id=(Split-Path -Leaf $JobRoot);attempt_id=$AttemptId;gpu=(& nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader,nounits|Select-Object -First 1).Trim();cuda_toolkit=(&(Join-Path $cudaPath 'bin\nvcc.exe')--version|Select-Object -Last 1).Trim();manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash.ToLowerInvariant();source_sha256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant();contract_sha256=(Get-FileHash $contract -Algorithm SHA256).Hash.ToLowerInvariant();binary_sha256=(Get-FileHash $binary -Algorithm SHA256).Hash.ToLowerInvariant();fresh_process_count=4;all_checkpoint_two_poison_invariant=$true;final_output_sha256=$final[0];address_fields_recorded=$false;result='pass'};$enc=New-Object System.Text.UTF8Encoding($false);$path=Join-Path $attemptRoot 'rig-receipt.json';[IO.File]::WriteAllText($path,(($receipt|ConvertTo-Json -Depth 4)+"`n"),$enc);$rh=(Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant();[IO.File]::WriteAllText((Join-Path $attemptRoot 'rig-receipt.sha256'),($rh+"  rig-receipt.json`n"),$enc);Write-Host "attempt_root=$attemptRoot";Write-Host "output_sha256=$($final[0])";Write-Host "rig_receipt_sha256=$rh";Write-Host result=pass
